int main() {
    int count;
    cin >> count;
    int sum = 0;

    // 1. for loop from int i = 0 to i < count
    // 2. read int reading from cin, add reading to sum
    // 3. after loop print: TOTAL RADIATION: <sum>

    return 0;
}

steps.solution:
#include <iostream>
using namespace std;

int main() {
    int count;
    cin >> count;
    int sum = 0;

    for (int i = 0; i < count; i++) {
        int reading;
        cin >> reading;
        sum += reading;
    }
    cout << "TOTAL RADIATION: " << sum << endl;

    return 0;
}
